<template>
  <div class="research-tool">
    <section class="audit-import"><div class="calculator-section-heading"><h2>导入数据表</h2><button type="button" class="tool-text-button" :disabled="loading" @click="example">载入问题示例</button></div><p class="tool-intro">支持 CSV、TSV、Excel .xlsx，或直接粘贴表格。第一行作为表头，最多 5,000 行、60 列，文件不超过 5 MB。</p>
      <div class="research-actions"><label class="audit-upload">{{ loading?'正在读取…':'选择本地文件' }}<input type="file" accept=".csv,.tsv,.xlsx" :disabled="loading" @change="importFile" /></label><button type="button" class="tool-text-button" :disabled="loading" @click="template">下载 CSV 模板</button><span class="tool-note">{{ fileName || '文件仅在浏览器处理，不上传。' }}</span></div>
      <label v-if="sheets.length>1" class="audit-sheet">工作表<select v-model.number="sheetIndex" @change="selectSheet"><option v-for="(sheet,i) in sheets" :key="i" :value="i">{{ sheet.sheet }}</option></select></label>
      <label class="audit-paste">粘贴 CSV 或制表符表格<textarea v-model="text" rows="5" maxlength="2000000" spellcheck="false" :disabled="loading" placeholder="sample_id,pH,SOC(g/kg)&#10;S01,6.8,12.5" /></label><div class="research-actions"><button type="button" class="tool-primary-button" :disabled="loading || !text.trim()" @click="readText">读取粘贴内容</button><button type="button" class="tool-text-button" :disabled="loading" @click="clear">清空数据</button></div>
      <p v-if="error" role="alert" class="calculator-error">{{ error }}</p><p v-if="demo" class="calculator-example-note">已载入合成问题示例，用于演示检查结果，不代表实测数据。</p>
    </section>
    <template v-if="table">
      <section class="audit-settings"><div class="calculator-section-heading"><h2>检查设置</h2><span class="tool-note">{{ table.rows.length }} 行 · {{ table.headers.length }} 列</span></div><div class="audit-options"><label>样本编号列<select v-model.number="idColumn"><option :value="-1">不检查编号重复</option><option v-for="(header,i) in table.headers" :key="i" :value="i">{{ header }}</option></select></label><label class="tool-checkbox"><input v-model="outliers" type="checkbox" />标记 1.5×IQR 疑似离群值</label></div><p class="tool-note">自动识别仅作为初始设置。请确认数值列、单位和范围；上下界留空时不做范围判断。</p>
        <div class="research-table-scroll"><table class="research-table"><thead><tr><th>字段</th><th>检查类型</th><th>预期单位</th><th>下界（含）</th><th>上界（含）</th></tr></thead><tbody><tr v-for="(rule,i) in rules" :key="i"><th scope="row">{{ table.headers[i] }}</th><td><select v-model="rule.kind" :aria-label="`${table.headers[i]}检查类型`"><option value="text">文本</option><option value="number">数值</option></select></td><td><input v-model="rule.unit" :disabled="rule.kind!=='number'" :aria-label="`${table.headers[i]}预期单位`" placeholder="可留空" maxlength="30" /></td><td><input v-model="rule.min" :disabled="rule.kind!=='number'" :aria-label="`${table.headers[i]}下界`" inputmode="decimal" placeholder="不限" /></td><td><input v-model="rule.max" :disabled="rule.kind!=='number'" :aria-label="`${table.headers[i]}上界`" inputmode="decimal" placeholder="不限" /></td></tr></tbody></table></div><button type="button" class="tool-primary-button" @click="run">开始体检</button>
      </section>
      <section v-if="output" class="audit-results" aria-live="polite"><div class="calculator-section-heading"><h2>体检结果</h2><button type="button" class="tool-text-button" @click="exportIssues">下载问题清单 CSV</button></div><p class="audit-summary">{{ output.rows }} 行、{{ output.columns }} 列，共 {{ output.issues.length }} 条检查记录：<strong>{{ output.errors }} 条格式错误</strong>，{{ output.warnings }} 条待核对提示。</p><p class="tool-note">检查记录数不等于样本数。未列出问题也不代表数据已获科学验证。</p>
        <div v-if="output.issues.length" class="audit-options"><label>显示<select v-model="severity"><option value="all">全部问题</option><option value="error">格式错误</option><option value="warning">待核对</option></select></label><span class="tool-note">{{ filtered.length }} 条，当前第 {{ page }} / {{ pages }} 页</span></div>
        <div v-if="output.issues.length" class="research-table-scroll"><table class="research-table audit-issue-table"><thead><tr><th>表格行号</th><th>字段</th><th>类型</th><th>原值</th><th>说明</th></tr></thead><tbody><tr v-for="(issue,i) in pageIssues" :key="i"><td>{{ issue.row }}</td><td>{{ issue.column }}</td><td><span :class="issue.severity==='error'?'audit-error-tag':'audit-warning-tag'">{{ issue.type }}</span></td><td>{{ issue.value || '空' }}</td><td>{{ issue.message }}</td></tr></tbody></table></div><p v-else class="audit-clear">当前设置下未发现问题。</p><div v-if="filtered.length>50" class="research-actions"><button type="button" class="tool-text-button" :disabled="page<=1" @click="page--">上一页</button><button type="button" class="tool-text-button" :disabled="page>=pages" @click="page++">下一页</button></div>
        <details class="audit-profile"><summary>查看各列缺失与数值范围</summary><div class="research-table-scroll"><table class="research-table"><thead><tr><th>字段</th><th>缺失</th><th>可解析数值</th><th>最小值</th><th>最大值</th></tr></thead><tbody><tr v-for="profile in output.profiles" :key="profile.header"><td>{{ profile.header }}</td><td>{{ profile.missing }}</td><td>{{ profile.numeric }}</td><td>{{ profile.mixed?'单位不一致，未统计':profile.min ?? '—' }}</td><td>{{ profile.mixed?'单位不一致，未统计':profile.max ?? '—' }}</td></tr></tbody></table></div></details>
      </section>
      <AuditResearchImport v-if="output" :table="table" :output="output" :id-column="idColumn" :file-name="fileName" :sheet-name="sheets[sheetIndex]?.sheet || ''" :demo="demo" @open-research="$emit('open-research', $event)" />
      <details class="audit-profile"><summary>查看原始数据预览（前 50 行）</summary><div class="research-table-scroll"><table class="research-table"><thead><tr><th v-for="(header,i) in table.headers" :key="i">{{ header }}</th></tr></thead><tbody><tr v-for="(row,i) in table.rows.slice(0,50)" :key="i"><td v-for="(cell,j) in row" :key="j">{{ cell || '空' }}</td></tr></tbody></table></div></details>
    </template>
    <section class="research-method"><h2>检查口径</h2><p>空白、NA、N/A、NULL、NaN、破折号和单独的短横线标记为缺失。重复编号与重复行只提示，不合并记录；混用单位只提示，不做换算。范围由你设置，不自动套用肥力或污染阈值。</p><p>IQR 使用排序后线性插值分位数；至少 4 个可比数值且 IQR 大于 0 时才筛查。离群不等于错误，文件末尾的空行会被忽略；其余原始单元格不会被删除、改写或填补。Excel 读取单元格现有值，不重新计算公式；旧 .xls 文件请先转换为 .xlsx。</p><a href="https://www.itl.nist.gov/div898/handbook/eda/section3/boxplot.htm" target="_blank" rel="noopener noreferrer">NIST · 箱线图与四分位距</a></section>
  </div>
</template>
<script setup>
import { computed, ref, watch } from 'vue'
import { auditTable, defaultRules, downloadBlob, parseDelimited, prepareTable, toCsv } from './tables.js'
import './research-tools.css'
import AuditResearchImport from './AuditResearchImport.vue'
defineEmits(['open-research'])
const text=ref(''), table=ref(null), rules=ref([]), idColumn=ref(-1), outliers=ref(true), output=ref(null), error=ref(''), demo=ref(false), loading=ref(false), fileName=ref(''), sheets=ref([]), sheetIndex=ref(0), severity=ref('all'), page=ref(1)
const filtered=computed(()=>output.value?.issues.filter(item=>severity.value==='all'||item.severity===severity.value)||[]), pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/50))), pageIssues=computed(()=>filtered.value.slice((page.value-1)*50,page.value*50))
watch(severity,()=>{page.value=1})
watch([rules,idColumn,outliers],()=>{output.value=null;error.value=''}, {deep:true,flush:'sync'})
watch(text,()=>{table.value=null;output.value=null;error.value='';demo.value=false}, {flush:'sync'})
function setTable(value){table.value=value;rules.value=defaultRules(value);idColumn.value=value.headers.findIndex(header=>/^(sample[_ -]?id|id|样本编号|样品编号|编号)$/i.test(header));output.value=null;error.value='';page.value=1}
function readText(){try{const value=parseDelimited(text.value);sheets.value=[];fileName.value='粘贴内容';setTable(value)}catch(e){table.value=null;output.value=null;error.value=e.message}}
async function importFile(event){const file=event.target.files[0];event.target.value='';if(!file)return;table.value=null;output.value=null;error.value='';sheets.value=[];demo.value=false;loading.value=true;fileName.value=file.name;try{if(file.size>5*1024*1024)throw new Error('文件超过 5 MB，请拆分后导入。');if(/\.xlsx$/i.test(file.name)){const {default:read}=await import('read-excel-file/browser');sheets.value=await read(file,{trim:false,parseNumber:value=>value});sheetIndex.value=0;selectSheet()}else if(/\.(csv|tsv)$/i.test(file.name)){setTable(parseDelimited(await file.text()))}else throw new Error('请选择 CSV、TSV 或 .xlsx 文件。')}catch(e){sheets.value=[];error.value='读取失败：'+(e.message||'文件格式无法识别。')}finally{loading.value=false}}
function selectSheet(){try{setTable(prepareTable(sheets.value[sheetIndex.value]?.data||[]))}catch(e){table.value=null;output.value=null;error.value=e.message}}
function clear(){text.value='';table.value=null;output.value=null;error.value='';fileName.value='';sheets.value=[];demo.value=false}
const sample='sample_id,pH,SOC(g/kg),note\nS01,6.5,12.0,表层\nS02,NA,15.0,表层\nS02,7.2,900 mg/kg,复测\nS04,错误,10.5,待核对\nS04,错误,10.5,待核对\nS06,6.8,120 g/kg,可疑高值'
function example(){text.value=sample;readText();demo.value=true}
function template(){downloadBlob(toCsv([['sample_id','pH','SOC(g/kg)','note'],['S01','6.8','12.5','示例，使用前替换']]),'soilmate-data-template.csv','text/csv;charset=utf-8')}
function run(){try{output.value=auditTable(table.value,rules.value,idColumn.value,outliers.value);error.value='';page.value=1}catch(e){output.value=null;error.value=e.message}}
function exportIssues(){downloadBlob(toCsv([['表格行号','字段','严重程度','问题类型','原值','说明'],...output.value.issues.map(item=>[item.row,item.column,item.severity==='error'?'格式错误':'待核对',item.type,item.value,item.message])]),'soilmate-data-issues.csv','text/csv;charset=utf-8')}
</script>
